import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';
import { createMSDFMaterial } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{imageUrl:string}} assets
 * @property {string[]} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {{load: (url:string)=>THREE.Texture}} textureLoader
 * @property {{texture:THREE.Texture}} fontAtlas
 * @property {{[key:string]: Function}} primitives
 */

export default function createNode(config, ctx) {
    // root object ------------------------------------------------------------
    const root = new THREE.Object3D();
    root.position.set(0, 3, 0);
    root.rotation.set(0, 0, 0);
    root.scale.set(1, 1, 1);

    // ------------------------------------------------------------------------
    // Image plane (hero headline background)
    // ------------------------------------------------------------------------
    const tex = ctx.textureLoader.load(config.assets.imageUrl);
    // source rect 512x320 → aspect 1.6
    const planeGeom = new THREE.PlaneGeometry(1.6, 1);
    const planeMat = new THREE.MeshBasicNodeMaterial({
        map: tex,
        transparent: true,
        depthWrite: false,
    });
    const planeMesh = new THREE.Mesh(planeGeom, planeMat);
    root.add(planeMesh);

    // ------------------------------------------------------------------------
    // Text plane – rendered with MSDF from the shared font atlas
    // ------------------------------------------------------------------------
    const txt = (Array.isArray(config.textContent) ? config.textContent[0] : config.textContent) || '';
    const textMaterial = createMSDFMaterial({
        map: ctx.fontAtlas.texture,
        color: new THREE.Color('#16161d'), // ink
        opacity: 1,
        // optional: set vertex/fragment node specifics if needed
    });

    // approximate size based on body scale (0.13) and character count
    const textWidth = txt.length * 0.07; // rough estimate per glyph
    const textHeight = 0.13;
    const textGeom = new THREE.PlaneGeometry(textWidth, textHeight);
    const textMesh = new THREE.Mesh(textGeom, textMaterial);
    // position slightly above the image plane
    textMesh.position.set(0, 0.6, 0.01);
    root.add(textMesh);

    // ------------------------------------------------------------------------
    // UserData: handlers placeholder & cleanup
    // ------------------------------------------------------------------------
    root.userData.handlers = {};

    const timelines = []; // keep any GSAP timelines (none for this node)

    root.userData.cleanup = () => {
        // dispose geometry & materials
        planeGeom.dispose();
        planeMat.dispose();
        tex.dispose();

        textGeom.dispose();
        textMaterial.dispose();

        // kill any GSAP timelines that might have been added later
        timelines.forEach((t) => {
            try {
                t.kill();
            } catch (_) {}
        });
        timelines.length = 0;
    };

    return root;
}
